from fractions import Fraction
from itertools import product

money = {"gadwall": 11, "german shepherd": 25, "wolf": 67}
diameter = Fraction(22)
box = tuple(map(Fraction, ("23.5", "28.7", "21.3")))

facts = {"wolf_struggles_to_find_food"}
if money["wolf"] > money["gadwall"] + money["german shepherd"]:
    facts.add("wolf_has_more_money_than_both_combined")
if all(diameter <= side for side in box):
    facts.add("wolf_basketball_fits_box")

# No movie-watching, abundant-food, or zebra-dancing fact is given.
rules = {
    "Rule1": ({"wolf_watches_pre_moon_landing_movie"}, "not_hug"),
    "Rule2": ({"wolf_basketball_fits_box"}, "hug"),
    "Rule3": ({"wolf_has_abundant_food"}, "not_hug"),
    "Rule4": ({"zebra_dances_with_walrus"}, "castle"),
    "Rule5": ({"wolf_has_more_money_than_both_combined"}, "hug"),
    # A wolf hugging the fish suffices for "at least one animal".
    "Rule6": ({"hug"}, "not_castle"),
}
preferred = {
    ("Rule1", "Rule2"), ("Rule1", "Rule5"),
    ("Rule3", "Rule2"), ("Rule3", "Rule5"),
    ("Rule4", "Rule6"),
}
opposite = {
    "hug": "not_hug", "not_hug": "hug",
    "castle": "not_castle", "not_castle": "castle",
}
literals = tuple(opposite)

# Exhaustively find self-consistent, supported conclusions. A priority
# defeats an opposing rule only when the preferred rule is applicable.
models = []
for bits in product((False, True), repeat=len(literals)):
    candidate = {lit for lit, present in zip(literals, bits) if present}
    available = facts | candidate
    applicable = {
        name for name, (antecedents, _) in rules.items()
        if antecedents <= available
    }
    conclusions = set()
    for name in applicable:
        conclusion = rules[name][1]
        attackers = {
            other for other in applicable
            if rules[other][1] == opposite[conclusion]
        }
        if all((name, other) in preferred for other in attackers):
            conclusions.add(conclusion)
    if conclusions == candidate:
        models.append(candidate)

print("Money test:", money["wolf"], ">", 
      money["gadwall"] + money["german shepherd"],
      "=", "wolf_has_more_money_than_both_combined" in facts)
print("Basketball fits box:", "wolf_basketball_fits_box" in facts)
print("Supported models:", [sorted(model) for model in models])

if not models:
    print("UNSUPPORTED")
    print("CHECK UNKNOWN")
else:
    if all("castle" in model and "not_castle" not in model for model in models):
        expected = "proved"
    elif all("not_castle" in model and "castle" not in model for model in models):
        expected = "disproved"
    else:
        expected = "unknown"

    submitted = "proven"
    normalized = {"proven": "proved"}.get(submitted, submitted)
    print("Expected result:", expected)
    print("CHECK PASS" if normalized == expected else "CHECK FAIL")
